<?php
require_once __DIR__ . '/layout.php';
require_once __DIR__ . '/cron_terminer_encheres.php';
$user = app_current_user();
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id) { app_error_page(404, 'Ce lot n’existe pas.'); }
$query = $pdo->prepare('SELECT p.*, c.nom AS categorie_nom, u.nom AS vendeur_nom,
    TIMESTAMPDIFF(SECOND,NOW(),p.date_fin) AS secondes_restantes,
    EXISTS(SELECT 1 FROM favoris f WHERE f.produit_id = p.id AND f.utilisateur_id = ?) AS favori
    FROM produits p JOIN categories c ON c.id = p.categorie_id LEFT JOIN utilisateurs u ON u.id = p.vendeur_id
    WHERE p.id = ? AND p.archive_le IS NULL');
$query->execute([$user['id'] ?? 0, $id]);
$product = $query->fetch();
if (!$product) { app_error_page(404, 'Ce lot n’est pas disponible.'); }
$closed = $product['statut'] !== 'en_cours' || (int) $product['secondes_restantes'] <= 0;
$owner = $user && $product['vendeur_id'] !== null && (int) $product['vendeur_id'] === (int) $user['id'];
$query = $pdo->prepare('SELECT e.montant, e.date_enchere, u.nom FROM encheres e JOIN utilisateurs u ON u.id = e.utilisateur_id WHERE e.produit_id = ? ORDER BY e.date_enchere DESC, e.montant DESC, e.utilisateur_id DESC LIMIT 50');
$query->execute([$id]); $history = $query->fetchAll();
$query = $pdo->prepare("SELECT p.*, c.nom AS categorie_nom, TIMESTAMPDIFF(SECOND,NOW(),p.date_fin) AS secondes_restantes,
    EXISTS(SELECT 1 FROM favoris f WHERE f.produit_id = p.id AND f.utilisateur_id = ?) AS favori
    FROM produits p JOIN categories c ON c.id = p.categorie_id WHERE p.categorie_id = ? AND p.id <> ? AND p.archive_le IS NULL AND p.statut = 'en_cours' AND p.date_fin > NOW() ORDER BY p.date_fin ASC, p.id DESC LIMIT 3");
$query->execute([$user['id'] ?? 0, $product['categorie_id'], $id]); $similar = $query->fetchAll();
app_page_start($product['nom'], 'produit');
?>
<div class="container"><nav class="breadcrumb" aria-label="Fil d’Ariane"><a href="index.php">Accueil</a><span>›</span><a href="index.php?categorie=<?= (int) $product['categorie_id'] ?>"><?= app_escape($product['categorie_nom']) ?></a><span>›</span><span>Lot #<?= $id ?></span></nav><div class="product-title"><div><p class="eyebrow">Vente aux enchères</p><h1><?= app_escape($product['nom']) ?></h1><p>Lot #<?= str_pad((string) $id, 5, '0', STR_PAD_LEFT) ?> · <?= app_escape($product['categorie_nom']) ?></p></div><?php if ($user): ?><button type="button" class="favorite-button" data-favorite data-product="<?= $id ?>" data-state="<?= $product['favori'] ? '1' : '0' ?>" aria-pressed="<?= $product['favori'] ? 'true' : 'false' ?>" aria-label="<?= $product['favori'] ? 'Retirer des favoris' : 'Ajouter aux favoris' ?>"><?= app_icon('heart') ?></button><?php else: ?><a class="favorite-button" href="login.php" aria-label="Se connecter pour ajouter aux favoris"><?= app_icon('heart') ?></a><?php endif; ?></div><div id="global-feedback" role="status" aria-live="polite"></div>
<div class="product-layout"><div class="product-photo"><img src="photo.php?id=<?= $id ?>" alt="<?= app_escape($product['nom']) ?>"></div><aside class="auction-box"><div class="auction-top"><div class="timer"><?= app_icon('clock') ?><span id="countdown"><?= $closed ? 'TERMINÉE' : 'Chargement…' ?></span></div><span id="auction-status" class="status-pill <?= $closed ? 'status-muted' : '' ?>"><?= $closed ? 'Terminée' : 'En cours' ?></span></div><p class="price-label">Prix actuel</p><div class="current-price" id="current-price"><?= number_format($product['prix_actuel'], 2, ',', ' ') ?> €</div><p class="auction-meta">Prix de départ : <?= number_format($product['prix_depart'], 2, ',', ' ') ?> €<br>Fin le <?= app_escape(date('d/m/Y à H:i', strtotime($product['date_fin']))) ?></p>
<?php if (!$closed && $user && !$owner): ?><form class="bid-form" id="bid-form"><input type="hidden" id="produit_id" value="<?= $id ?>"><input type="hidden" id="csrf-enchere" value="<?= app_escape(app_csrf_token()) ?>"><label for="montant">Votre offre (€)</label><div class="bid-input-row"><input type="number" id="montant" name="montant" min="0.01" step="0.01" max="9999999999999.99" placeholder="Votre montant" required><button type="submit" class="button button-yellow">Enchérir <?= app_icon('hammer') ?></button></div></form><p class="bid-note">Votre offre doit être supérieure au prix actuel. Retrouvez ensuite son enregistrement dans l’historique.</p>
<?php elseif (!$closed && $owner): ?><div class="notice">Vous ne pouvez pas enchérir sur votre propre annonce.</div><a class="button button-outline button-wide" href="mes_annonces.php">Mes annonces</a>
<?php elseif (!$closed): ?><p class="muted">Connectez-vous pour participer à cette vente.</p><a class="button button-yellow button-wide" href="login.php">Me connecter pour enchérir</a><?php endif; ?>
<div id="auction-closed-message" class="closed-message" role="status" <?= $closed ? '' : 'hidden' ?>>Cette enchère est terminée. Les offres ne sont plus acceptées.</div><div id="bid-message" role="status" aria-live="polite"></div></aside></div>
<div class="product-details-grid"><div><section class="detail-section"><h2>Description du bien</h2><p class="description"><?= app_escape($product['description']) ?></p></section><section class="detail-section"><h2>Informations de vente</h2><dl class="key-values"><div><dt>Type de vente</dt><dd>Vente aux enchères</dd></div><div><dt>Catégorie</dt><dd><?= app_escape($product['categorie_nom']) ?></dd></div><div><dt>Prix de départ</dt><dd><?= number_format($product['prix_depart'], 2, ',', ' ') ?> €</dd></div><div><dt>Fin de la vente</dt><dd><?= app_escape(date('d/m/Y H:i', strtotime($product['date_fin']))) ?></dd></div></dl></section><section class="seller-info"><h3>Vendeur</h3><p><?= app_escape($product['vendeur_nom'] ?? 'Non renseigné') ?></p></section></div><section class="history-box"><h2>Historique des offres</h2><p class="muted" style="font-size:12px">Les 50 offres les plus récentes, de la plus récente à la plus ancienne.</p><ul id="history-list"><?php if (!$history): ?><li class="empty">Aucune offre pour le moment.</li><?php endif; ?><?php foreach ($history as $bid): ?><li><span class="user-name"><?= app_escape($bid['nom']) ?></span><span class="bid-amount"><?= number_format($bid['montant'], 2, ',', ' ') ?> €</span><span class="bid-date"><?= app_escape(date('d/m H:i', strtotime($bid['date_enchere']))) ?></span></li><?php endforeach; ?></ul><p id="history-feedback" role="status" aria-live="polite"></p></section></div>
<?php if ($similar): ?><section class="section"><h2>D’autres biens à découvrir</h2><div class="similar-grid"><?php foreach ($similar as $item) { app_product_card($item); } ?></div></section><?php endif; ?>
</div><script type="application/json" id="auction-config"><?= json_encode(['id' => $id, 'closed' => $closed, 'remainingSeconds' => max(0, (int) $product['secondes_restantes'])], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?></script><script src="assets/enchere.js?v=20261017b" defer></script>
<?php app_page_end(); ?>
